const input = $input.all();
const out = [];

for (const item of input) {
  const json = item.json;
  if (json.target === 'airtable') {
    out.push(item);
  }
}

return out;

// Resolve Conflicts â€” pass-through for now
// Conflict policy application is a Roadmap item.

const input = $input.all();
const writeOps = [];

for (const item of input) {
  const json = item.json;
  if (json.operation === 'conflict') {
    // No conflict policy yet. Drop for now.
    continue;
  }
  writeOps.push(item);
}

return writeOps;

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  // n8n wraps Airtable responses one of two ways depending on config
  let records = null;
  if (Array.isArray(j) && j[0] && Array.isArray(j[0].records)) records = j[0].records;
  else if (Array.isArray(j.records)) records = j.records;
  else if (j.body && Array.isArray(j.body.records)) records = j.body.records;

  if (records) {
    for (const rec of records) {
      out.push({ json: { _source: 'airtable', ...rec } });
    }
  }
}
return out;

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  let results = null;
  if (Array.isArray(j) && j[0] && Array.isArray(j[0].results)) results = j[0].results;
  else if (Array.isArray(j.results)) results = j.results;
  else if (j.body && Array.isArray(j.body.results)) results = j.body.results;

  if (results) {
    for (const page of results) {
      if (page.object === 'page') {
        out.push({ json: { _source: 'notion', ...page } });
      }
    }
  }
}
return out;

const inputItems = $input.all();
const syncStateRows = $('Read Sync State').all().map(item => item.json);
const syncStateByAirtableId = {};
const syncStateByNotionId = {};

for (const row of syncStateRows) {
  if (row.airtable_record_id) syncStateByAirtableId[row.airtable_record_id] = row;
  if (row.notion_page_id)     syncStateByNotionId[row.notion_page_id]     = row;
}

const airtableItems = [];
const notionItems = [];

for (const item of inputItems) {
  const json = item.json;
  if (json._source === 'airtable') airtableItems.push(json);
  else if (json._source === 'notion') notionItems.push(json);
}

const operations = [];

for (const airtableRecord of airtableItems) {
  const airtableId = airtableRecord.id;
  const state = syncStateByAirtableId[airtableId];
  const currentAirtableModified = (airtableRecord.fields && airtableRecord.fields['Last Modified']) || null;

  if (!state) {
    operations.push({
      operation: 'create', target: 'notion',
      airtable_record_id: airtableId, notion_page_id: null,
      payload: mapAirtableToNotionProperties(airtableRecord.fields || {}),
      current_airtable_modified: currentAirtableModified,
      current_notion_edited: null, previous_status: null
    });
    continue;
  }

  const currentTs = currentAirtableModified ? new Date(currentAirtableModified).getTime() : 0;
  const lastSyncedTs = state.last_airtable_modified_at ? new Date(state.last_airtable_modified_at).getTime() : 0;
  const airtableChanged = Math.abs(currentTs - lastSyncedTs) > 2000;

  const notionPage = notionItems.find(p => p.id === state.notion_page_id);
  if (!notionPage) continue;

  const currentNotionEdited = notionPage.last_edited_time || null;
  const notionTs = currentNotionEdited ? new Date(currentNotionEdited).getTime() : 0;
  const lastSyncedNotionTs = state.last_notion_edited_at ? new Date(state.last_notion_edited_at).getTime() : 0;
  const notionChanged = Math.abs(notionTs - lastSyncedNotionTs) > 2000;

  if (airtableChanged && notionChanged) {
    operations.push({
      operation: 'conflict', target: 'both',
      airtable_record_id: airtableId, notion_page_id: state.notion_page_id,
      payload: { airtable_fields: airtableRecord.fields || {}, notion_properties: notionPage.properties || null },
      current_airtable_modified: currentAirtableModified,
      current_notion_edited: currentNotionEdited,
      previous_status: state.current_status || 'active'
    });
  } else if (airtableChanged) {
    operations.push({
      operation: 'update', target: 'notion',
      airtable_record_id: airtableId, notion_page_id: state.notion_page_id,
      payload: mapAirtableToNotionProperties(airtableRecord.fields || {}),
      current_airtable_modified: currentAirtableModified,
      current_notion_edited: state.last_notion_edited_at,
      previous_status: state.current_status || 'active'
    });
  } else if (notionChanged && notionPage.properties) {
    operations.push({
      operation: 'update', target: 'airtable',
      airtable_record_id: airtableId, notion_page_id: state.notion_page_id,
      payload: mapNotionToAirtableFields(notionPage.properties),
      current_airtable_modified: state.last_airtable_modified_at,
      current_notion_edited: currentNotionEdited,
      previous_status: state.current_status || 'active'
    });
  }
}

for (const notionPage of notionItems) {
  const notionId = notionPage.id;
  const state = syncStateByNotionId[notionId];
  if (!state) {
    operations.push({
      operation: 'create', target: 'airtable',
      airtable_record_id: null, notion_page_id: notionId,
      payload: mapNotionToAirtableFields(notionPage.properties || {}),
      current_airtable_modified: null,
      current_notion_edited: notionPage.last_edited_time || null,
      previous_status: null
    });
  }
}

const outputItems = operations.length > 0
  ? operations.map(op => ({ json: op }))
  : [{ json: { _noop: true } }];

return outputItems;

function mapAirtableToNotionProperties(airtableFields) {
  const properties = {};
  if (airtableFields['Name'] !== undefined) properties['Name'] = { title: [{ text: { content: String(airtableFields['Name'] || '') } }] };
  if (airtableFields['Status'] !== undefined) properties['Status'] = { status: { name: String(airtableFields['Status'] || '') } };
  if (airtableFields['Priority'] !== undefined) {
    const v = airtableFields['Priority'];
    properties['Priority'] = { number: typeof v === 'number' ? v : (v === null || v === '' ? null : Number(v)) };
  }
  if (airtableFields['Due Date'] !== undefined) properties['Due Date'] = { date: { start: airtableFields['Due Date'] ? String(airtableFields['Due Date']) : null } };
  if (airtableFields['Assignee'] !== undefined) properties['Assignee'] = { rich_text: [{ text: { content: String(airtableFields['Assignee'] || '') } }] };
  return properties;
}

function mapNotionToAirtableFields(notionProperties) {
  const fields = {};
  if (notionProperties['Name'] && notionProperties['Name'].title) fields['Name'] = notionProperties['Name'].title.map(t => t.plain_text).join('');
  if (notionProperties['Status'] && notionProperties['Status'].status) fields['Status'] = notionProperties['Status'].status.name;
  if (notionProperties['Priority'] && notionProperties['Priority'].number !== undefined) fields['Priority'] = notionProperties['Priority'].number;
  if (notionProperties['Due Date'] && notionProperties['Due Date'].date) fields['Due Date'] = notionProperties['Due Date'].date.start;
  if (notionProperties['Assignee'] && notionProperties['Assignee'].rich_text) fields['Assignee'] = notionProperties['Assignee'].rich_text.map(t => t.plain_text).join('');
  return fields;
}
